package in.finseq.insurance;
import android.app.*;import android.content.*;import org.json.*;import java.util.*;
public final class AttendanceReminderScheduler{
 private AttendanceReminderScheduler(){}
 public static void sync(Context c,JSONObject config){try{JSONObject r=config.optJSONObject("reminder"),s=config.optJSONObject("shift");if(r==null||s==null||!r.optBoolean("enabled",false))return;String[] hm=s.optString("start","08:00").split(":");int h=Integer.parseInt(hm[0]),m=Integer.parseInt(hm[1]);int before=Math.max(0,r.optInt("minutes_before_shift",15)),late=Math.max(0,r.optInt("late_reminder_minutes",1));schedule(c,71001,h,m,-before,"SHIFT_REMINDER");schedule(c,71002,h,m,late,"LATE_REMINDER");}catch(Exception ignored){}}
 private static void schedule(Context c,int req,int h,int m,int offset,String kind){Calendar cal=Calendar.getInstance();cal.set(Calendar.HOUR_OF_DAY,h);cal.set(Calendar.MINUTE,m);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);cal.add(Calendar.MINUTE,offset);if(cal.getTimeInMillis()<=System.currentTimeMillis())cal.add(Calendar.DAY_OF_YEAR,1);Intent i=new Intent(c,AttendanceReminderReceiver.class).setAction(kind);PendingIntent pi=PendingIntent.getBroadcast(c,req,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(am!=null)am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi);}
 public static void snooze(Context c,int minutes){Calendar cal=Calendar.getInstance();cal.add(Calendar.MINUTE,Math.max(1,minutes));Intent i=new Intent(c,AttendanceReminderReceiver.class).setAction("SNOOZE_REMINDER");PendingIntent pi=PendingIntent.getBroadcast(c,71003,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(am!=null)am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi);}
}